MODULES.WeatherFx = function()
	-- WeatherFx (ModuleScript)
	-- Blends the sky between a clear Florida afternoon and a storm by the scenario's cloud cover.
	local Lighting = game:GetService("Lighting")
	local ServerStorage = game:GetService("ServerStorage")
	local TweenService = game:GetService("TweenService")

	local WeatherFx = {}

	local function ensure(parent, class, name)
		local x = parent:FindFirstChild(name)
		if not x then
			x = Instance.new(class)
			x.Name = name
			x.Parent = parent
		end
		return x
	end

	local targets = {
		lighting = Lighting,
		atmosphere = ensure(Lighting, "Atmosphere", "Atmosphere"),
		grade = ensure(Lighting, "ColorCorrectionEffect", "Grade"),
		clouds = ensure(workspace.Terrain, "Clouds", "Clouds"),
	}

	local CLEAR = {
		lighting = { Brightness = 3, OutdoorAmbient = Color3.fromRGB(118, 120, 126) },
		atmosphere = { Density = 0.36, Haze = 1.8, Glare = 0.35, Color = Color3.fromRGB(200, 204, 196), Decay = Color3.fromRGB(108, 118, 112) },
		grade = { Brightness = 0, Contrast = 0.12, Saturation = -0.06, TintColor = Color3.fromRGB(255, 248, 236) },
		clouds = { Cover = 0.5, Density = 0.55, Color = Color3.new(1, 1, 1) },
	}
	local STORM = {
		lighting = { Brightness = 1.1, OutdoorAmbient = Color3.fromRGB(78, 84, 96) },
		atmosphere = { Density = 0.58, Haze = 2.6, Glare = 0, Color = Color3.fromRGB(104, 110, 120), Decay = Color3.fromRGB(64, 70, 84) },
		grade = { Brightness = -0.04, Contrast = 0.16, Saturation = -0.3, TintColor = Color3.fromRGB(212, 222, 236) },
		clouds = { Cover = 0.96, Density = 0.9, Color = Color3.fromRGB(105, 110, 120) },
	}

	-- k = 0 is CLEAR, k = 1 is STORM
	local function blend(k)
		local out = {}
		for key, props in pairs(CLEAR) do
			out[key] = {}
			for name, a in pairs(props) do
				local b = STORM[key][name]
				out[key][name] = typeof(a) == "Color3" and a:Lerp(b, k) or a + (b - a) * k
			end
		end
		return out
	end

	local function set(preset, seconds)
		for key, props in pairs(preset) do
			if seconds > 0 then
				TweenService:Create(targets[key], TweenInfo.new(seconds, Enum.EasingStyle.Sine), props):Play()
			else
				for name, v in pairs(props) do targets[key][name] = v end
			end
		end
	end

	local function emitter()
		local part = workspace:FindFirstChild("RainEmitter")
		return part and part:FindFirstChildOfClass("ParticleEmitter")
	end

	-- The flood. FloodWater is a site wide plane that sits under the ground until a water event raises it.
	-- The scenarios speak in depth_mm (the contract); the twin exaggerates so the rise reads on screen:
	-- 20 mm is shin deep on the pad (gauge about 1 ft), 60 mm thigh deep (3 ft), 100 mm chest deep (4.7 ft).
	local WATER_Y = -0.5
	local STUDS_PER_MM = 2.4 / 60
	local RISE_SECONDS = 8

	-- The river crossing: the river side climbs from its normal level at -3, the land side floods only once the river
	-- passes the levee top at 4. 100 mm brings the river to the levee top, 120 mm and up overtops it.
	local RIVER_NORMAL, LEVEE_TOP, RIVER_PER_MM = -3, 4, 0.07
	local function setRiver(depth_mm, instant)
		local riverTop = RIVER_NORMAL + math.max(0, depth_mm) * RIVER_PER_MM
		local landTop = riverTop > LEVEE_TOP and (riverTop - 0.6) or -1.2
		local plan = {
			{ workspace:FindFirstChild("RiverFloodWater"), riverTop, depth_mm > 0 and 0.2 or 1 },
			{ workspace:FindFirstChild("LandFloodWater"), landTop, riverTop > LEVEE_TOP and 0.25 or 1 },
		}
		for _, p in ipairs(plan) do
			local water, top, transparency = p[1], p[2], p[3]
			if water then
				local goal = { Transparency = transparency, CFrame = CFrame.new(water.CFrame.Position.X, top - water.Size.Y / 2, water.CFrame.Position.Z) }
				if instant then
					for name, v in pairs(goal) do water[name] = v end
				else
					TweenService:Create(water, TweenInfo.new(RISE_SECONDS, Enum.EasingStyle.Sine), goal):Play()
				end
			end
		end
		workspace:SetAttribute("RiverOvertop", riverTop > LEVEE_TOP)
	end

	-- the rain falls over whichever setting is active
	function WeatherFx.moveRain(position)
		local part = workspace:FindFirstChild("RainEmitter")
		if part then part.CFrame = CFrame.new(position + Vector3.new(0, 150, 0)) end
	end

	function WeatherFx.setWater(depth_mm, instant)
		setRiver(depth_mm, instant)
		local top = depth_mm > 0 and math.min(6, 0.3 + depth_mm * STUDS_PER_MM) or -1
		workspace:SetAttribute("WaterSurface", math.max(WATER_Y, top)) -- Wildlife floats the boat, logs, pads, and gators to this
		local water = workspace:FindFirstChild("FloodWater")
		if not water then return end
		local goal = {
			Transparency = depth_mm > 0 and 0.28 or 1,
			CFrame = CFrame.new(water.CFrame.Position.X, top - water.Size.Y / 2, water.CFrame.Position.Z),
		}
		if instant then
			for name, v in pairs(goal) do water[name] = v end
		else
			TweenService:Create(water, TweenInfo.new(RISE_SECONDS, Enum.EasingStyle.Sine), goal):Play()
		end
	end

	-- the sun's position comes from the scenario clock (ScenarioEngine), the weather only dims and tints it
	function WeatherFx.setClock(hours)
		Lighting.ClockTime = hours
	end

	function WeatherFx.reset()
		set(blend(0), 0)
		workspace:SetAttribute("Storm", 0)
		workspace:SetAttribute("Rain", 0)
		workspace.GlobalWind = Vector3.new(4, 0, 0)
		local e = emitter()
		if e then e.Enabled, e.Rate = false, 0 end
		WeatherFx.setWater(0, true)
		for _, n in ipairs({ "Gator", "HazardPin" }) do
			local x = workspace:FindFirstChild(n)
			if x then x:Destroy() end
		end
	end

	-- a crew hazard report as it shows on the site map: a pin with the report, and the 30 ft buffer on the ground
	local function hazardPin(at, title, detail)
		local m = Instance.new("Model")
		m.Name = "HazardPin"
		local function piece(size, cf, color, material, shape)
			local p = Instance.new("Part")
			p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch, p.CastShadow = true, false, false, false, false
			p.Size, p.CFrame, p.Color, p.Material = size, cf, color, material or Enum.Material.SmoothPlastic
			if shape then p.Shape = shape end
			p.Parent = m
			return p
		end
		local yellow = Color3.fromRGB(255, 200, 0)
		piece(Vector3.new(0.25, 7, 0.25), CFrame.new(at + Vector3.new(0, 3.5, 0)), Color3.fromRGB(40, 40, 46), Enum.Material.Metal)
		local head = piece(Vector3.new(1.4, 1.4, 1.4), CFrame.new(at + Vector3.new(0, 7.6, 0)), yellow, Enum.Material.Neon, Enum.PartType.Ball)
		-- 30 ft is about 28 studs across at our 1 stud to 1.1 ft
		local ring = piece(Vector3.new(0.12, 28, 28), CFrame.new(at + Vector3.new(0, 0.12, 0)) * CFrame.Angles(0, 0, math.rad(90)), yellow, Enum.Material.Neon, Enum.PartType.Cylinder)
		ring.Transparency = 0.75
		local bb = Instance.new("BillboardGui")
		bb.Size, bb.StudsOffset, bb.MaxDistance, bb.LightInfluence = UDim2.fromOffset(250, 58), Vector3.new(0, 2.4, 0), 250, 0
		bb.Parent = head
		local function line(text, y, h, color, font)
			local t = Instance.new("TextLabel")
			t.BackgroundColor3, t.BackgroundTransparency, t.BorderSizePixel = Color3.fromRGB(14, 16, 22), 0.15, 0
			t.Size, t.Position = UDim2.fromScale(1, h), UDim2.fromScale(0, y)
			t.Font, t.TextScaled, t.TextColor3, t.Text = font, true, color, text
			t.Parent = bb
		end
		line(title, 0, 0.55, yellow, Enum.Font.GothamBold)
		line(detail, 0.55, 0.45, Color3.fromRGB(236, 238, 243), Enum.Font.GothamMedium)
		m.Parent = workspace
	end

	function WeatherFx.apply(e)
		local k = math.clamp(((e.clouds or 0) - 0.2) / 0.6, 0, 1)
		set(blend(k), 4)
		workspace:SetAttribute("Storm", k) -- Wildlife flushes the egrets past 0.6
		workspace:SetAttribute("Rain", e.rain or 0) -- Ambience fades the rain loop to this
		-- wind from the scenario's gust (mph), blowing east off the storm: bends the rain, the grass, and the clouds
		workspace.GlobalWind = Vector3.new(math.max(4, (e.gust or 0) * 0.8), 0, (e.gust or 0) * 0.15)
		local rain = emitter()
		if rain then
			rain.Enabled = (e.rain or 0) > 0
			rain.Rate = math.clamp((e.rain or 0) * 12, 0, 800) -- the worst cells come down in sheets
		end
	end

	function WeatherFx.spawnGator()
		if workspace:FindFirstChild("Gator") then return end
		local template = ServerStorage:FindFirstChild("Gator")
		local spot = workspace:FindFirstChild("GatorSpot")
		if template and spot then
			local g = template:Clone()
			g:PivotTo(spot.CFrame)
			g.Parent = workspace
			-- pinned where the crew saw it, centered on where it crawls to
			local at = (spot.CFrame * CFrame.new(0, -1, -8)).Position
			hazardPin(at, "HAZARD REPORT  ·  ALLIGATOR", "Crew photo, tagged and shared  ·  30 ft buffer")
		end
	end

	return WeatherFx

end

MODULES.Lightning = function()
	-- Lightning (ModuleScript)
	local Debris = game:GetService("Debris")
	local Lighting = game:GetService("Lighting")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local TweenService = game:GetService("TweenService")

	local events = ReplicatedStorage:WaitForChild("SimEvents")
	local flashEvent = ReplicatedStorage:WaitForChild("FlashEvent")
	local strikeRadar = ReplicatedStorage:WaitForChild("StrikeRadar")

	local Lightning = {}
	Lightning.STUDS_PER_MILE = 120 -- a 15 mile bolt lands 1800 studs out, near enough to see through the haze
	local CLOUD_HEIGHT = 900
	local BOLT_COLOR = Color3.fromRGB(225, 235, 255)
	local BASE_EXPOSURE = Lighting.ExposureCompensation
	local rng = Random.new()

	-- strikes are measured from the active setting's beacon: the main site, or the river crossing
	local function origin()
		local river = workspace:FindFirstChild("RiverBeacon")
		if workspace:GetAttribute("ActiveSite") == "river" and river then
			return river:GetPivot().Position
		end
		return workspace.Beacon:GetPivot().Position
	end

	-- bearing 0 is north (negative Z), 90 is east (positive X)
	function Lightning.groundPoint(bearing, miles)
		local o = origin()
		local r = miles * Lightning.STUDS_PER_MILE
		local x = o.X + math.sin(math.rad(bearing)) * r
		local z = o.Z - math.cos(math.rad(bearing)) * r
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = { workspace.Beacon, workspace:FindFirstChild("RiverBeacon") }
		local hit = workspace:Raycast(Vector3.new(x, 2000, z), Vector3.new(0, -4000, 0), params)
		return hit and hit.Position or Vector3.new(x, 0, z)
	end

	function Lightning.fromPosition(pos)
		local o = origin()
		local dx, dz = pos.X - o.X, pos.Z - o.Z
		local miles = math.sqrt(dx * dx + dz * dz) / Lightning.STUDS_PER_MILE
		local bearing = (math.deg(math.atan2(dx, -dz)) + 360) % 360
		return bearing, miles
	end

	local function segment(a, b, width, parts)
		local p = Instance.new("Part")
		p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch, p.CastShadow = true, false, false, false, false
		p.Material = Enum.Material.Neon
		p.Color = BOLT_COLOR
		p.Size = Vector3.new(width, width, (b - a).Magnitude)
		p.CFrame = CFrame.lookAt((a + b) / 2, b)
		p.Name = "Bolt"
		p.Parent = workspace
		table.insert(parts, p)
	end

	-- jagged channel from a to b that thins toward b
	local function channel(a, b, width, steps, jitter, parts)
		local points = { a }
		for i = 1, steps - 1 do
			local base = a:Lerp(b, i / steps)
			table.insert(points, base + Vector3.new(rng:NextNumber(-jitter, jitter), 0, rng:NextNumber(-jitter, jitter)))
		end
		table.insert(points, b)
		for i = 1, #points - 1 do
			segment(points[i], points[i + 1], width * (1 - 0.4 * i / #points), parts)
		end
		return points
	end

	function Lightning.strike(bearing, miles)
		local ground = Lightning.groundPoint(bearing, miles)
		local top = Vector3.new(ground.X, CLOUD_HEIGHT, ground.Z)
		local width = math.max(3, miles * 0.8)
		local parts = {}

		-- 1. draw the bolt, a main channel and two thinner branches
		local main = channel(top, ground, width, rng:NextInteger(7, 9), 70, parts)
		local impact = parts[#main - 1]
		for _ = 1, 2 do
			local from = main[rng:NextInteger(2, #main - 2)]
			local drop = (from.Y - ground.Y) * rng:NextNumber(0.25, 0.45)
			local to = from + Vector3.new(rng:NextNumber(-160, 160), -drop, rng:NextNumber(-160, 160))
			channel(from, to, width * 0.45, 3, 40, parts)
		end
		local light = Instance.new("PointLight")
		light.Brightness, light.Range, light.Color = 20, 60, BOLT_COLOR
		light.Parent = impact
		Lighting.ExposureCompensation = BASE_EXPOSURE + 1.5

		-- 2. physical path: every client flashes white and schedules thunder
		flashEvent:FireAllClients(miles)
		strikeRadar:FireAllClients(bearing, miles)

		-- 3. data path: the Bridge posts the strike
		events.Strike:Fire(bearing, miles)

		-- a return stroke flickers once, then the channel fades. Nothing here yields.
		local function setAll(t)
			for _, p in ipairs(parts) do p.Transparency = t end
		end
		task.delay(0.05, setAll, 1)
		task.delay(0.09, setAll, 0)
		task.delay(0.14, function()
			Lighting.ExposureCompensation = BASE_EXPOSURE
			for _, p in ipairs(parts) do
				TweenService:Create(p, TweenInfo.new(0.35), { Transparency = 1 }):Play()
				Debris:AddItem(p, 0.4)
			end
		end)
		print(("[Lightning] strike bearing %d miles %.1f"):format(bearing, miles))
	end

	return Lightning

end

MODULES.ScenarioEngine = function()
	-- ScenarioEngine (ModuleScript)
	local RunService = game:GetService("RunService")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")

	local Scenarios = req("Scenarios")
	local Lightning = req("Lightning")
	local WeatherFx = req("WeatherFx")
	local events = ReplicatedStorage:WaitForChild("SimEvents")

	local Engine = {}
	Engine.Changed = Instance.new("BindableEvent")

	local state = {
		scenario = nil, key = nil, name = "", clockStart = "13:00",
		simTime = 0, speed = 60, playing = false, fired = {}, note = "",
		duration = 0, markers = {},
	}

	-- duration and markers let the panel draw a timeline with a tick for every strike, flood step, and briefing
	function Engine.snapshot()
		return {
			key = state.key, name = state.name, clockStart = state.clockStart,
			simTime = state.simTime, speed = state.speed, playing = state.playing, note = state.note,
			duration = state.duration, markers = state.markers,
		}
	end

	-- the sun follows the scenario's clock, held between early morning and sunset so the site stays readable
	local function sun()
		local h, m = state.clockStart:match("(%d+):(%d+)")
		local hours = (tonumber(h) * 60 + tonumber(m) + state.simTime / 60) / 60
		WeatherFx.setClock(math.clamp(hours % 24, 7.2, 18.6))
	end

	local function emit()
		Engine.Changed:Fire(Engine.snapshot())
	end

	function Engine.load(key)
		local sc = Scenarios[key]
		if not sc then warn("[Engine] unknown scenario " .. tostring(key)) return end
		state.scenario, state.key, state.name = sc, key, sc.name
		state.clockStart = sc.clockStart or "13:00"
		state.simTime, state.speed, state.playing = 0, sc.speed or 60, false
		state.fired, state.note = {}, ""
		state.duration, state.markers = 0, {}
		for _, e in ipairs(sc.events) do
			state.duration = math.max(state.duration, e.t)
			if e.type ~= "weather" then
				table.insert(state.markers, { t = e.t, type = e.type, miles = e.miles })
			end
		end
		state.duration += 300
		WeatherFx.reset()
		sun()
		emit()
	end

	function Engine.play()
		if state.scenario then state.playing = true emit() end
	end

	function Engine.pause()
		state.playing = false
		emit()
	end

	function Engine.setSpeed(s)
		state.speed = math.clamp(s, 1, 1200)
		emit()
	end

	local function dispatch(e)
		if e.type == "strike" then
			Lightning.strike(e.bearing, e.miles)
		elseif e.type == "weather" then
			WeatherFx.apply(e)
			events.Weather:Fire({ temp_c = e.temp_c, humidity = e.humidity, precip_mm = e.rain or 0, gust = e.gust })
		elseif e.type == "water" then
			WeatherFx.setWater(e.depth_mm)
			events.Water:Fire(e.depth_mm)
		elseif e.type == "wildlife" then
			WeatherFx.spawnGator()
		elseif e.type == "note" then
			state.note = e.text
			emit()
		end
		print(("[Engine] t=%d %s"):format(e.t, e.type))
	end

	local acc = 0
	RunService.Heartbeat:Connect(function(dt)
		if not state.playing or not state.scenario then return end
		state.simTime += dt * state.speed
		for i, e in ipairs(state.scenario.events) do
			if not state.fired[i] and e.t <= state.simTime then
				state.fired[i] = true
				dispatch(e)
			end
		end
		acc += dt
		if acc >= 0.5 then
			acc = 0
			sun()
			emit()
		end
	end)

	-- instant hazards: fire one event now, through the same path as a scenario's timeline
	function Engine.fire(e)
		local now = table.clone(e)
		now.t = math.floor(state.simTime) -- stamped with the current sim time, as if it were on the timeline
		dispatch(now)
		emit()
	end

	function Engine.loadedKey()
		return state.key
	end

	function Engine.isPlaying()
		return state.playing
	end

	return Engine

end

MODULES.SceneBuilder = function()
	-- SceneBuilder (ModuleScript in ServerScriptService/World)
	-- Builds the whole jobsite from code: a Florida swamp edge with cypress, moss, reeds, lily pads,
	-- alligators and egrets, plus the beacon, the work zone, equipment, poles, and every instance the World scripts look up by name (simulator guide 2.2).
	-- Run it once in edit mode from the Command Bar, then save and publish:
	--   require(game.ServerScriptService.World.SceneBuilder).build()
	-- Re-running wipes the terrain and everything named in OWNED, then rebuilds it the same way.
	-- Nothing is uploaded; every part is a plain Part.

	local Lighting = game:GetService("Lighting")
	local Players = game:GetService("Players")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local ServerStorage = game:GetService("ServerStorage")

	local WeatherFx = req("WeatherFx")

	local Builder = {}

	local OWNED = { "Site", "Beacon", "ZonePart", "SiteBillboard", "Excavator", "RainEmitter", "GatorSpot", "FloodWater", "SpawnLocation", "Baseplate", "ConditionsBoard", "ConditionsBoardRiver", "RiverBeacon", "RiverFloodWater", "LandFloodWater" }
	local SITE_NAME = "SEMINOLE · SITE 12" -- the beacon site, Putnam County FL
	local ZONE = 60 -- work zone is ZONE x ZONE studs, centered on the beacon at the origin
	-- open water of the swamp east and south of the site, { center, radius }
	local SWAMP = {
		{ Vector3.new(150, 0, -60), 70 }, { Vector3.new(205, 0, 45), 85 }, { Vector3.new(170, 0, 150), 60 },
		{ Vector3.new(265, 0, -150), 75 }, { Vector3.new(40, 0, -235), 50 },
	}
	local WATER_Y = -0.5 -- water surface

	local C = {
		steel = Color3.fromRGB(78, 82, 90),
		concrete = Color3.fromRGB(168, 165, 158),
		dark = Color3.fromRGB(32, 34, 40),
		black = Color3.fromRGB(10, 10, 12),
		panel = Color3.fromRGB(18, 20, 26),
		safety = Color3.fromRGB(255, 184, 28),
		orange = Color3.fromRGB(240, 110, 30),
		white = Color3.fromRGB(236, 236, 230),
		green = Color3.fromRGB(40, 210, 100),
		yellow = Color3.fromRGB(255, 190, 0),
		red = Color3.fromRGB(235, 40, 40),
		dim = Color3.fromRGB(150, 155, 165),
		glass = Color3.fromRGB(140, 175, 195),
		tire = Color3.fromRGB(26, 26, 28),
		wood = Color3.fromRGB(105, 82, 60),
		bark = Color3.fromRGB(88, 70, 54),
		lcd = Color3.fromRGB(130, 200, 60),
		lcdText = Color3.fromRGB(20, 40, 10),
		leaves = { Color3.fromRGB(62, 96, 56), Color3.fromRGB(74, 108, 60), Color3.fromRGB(56, 86, 62) },
		moss = Color3.fromRGB(128, 138, 108),
		pine = Color3.fromRGB(48, 78, 46),
		pineBark = Color3.fromRGB(96, 72, 54),
		lily = Color3.fromRGB(72, 112, 48),
		reed = Color3.fromRGB(118, 138, 70),
		cattail = Color3.fromRGB(95, 62, 38),
		gator = Color3.fromRGB(50, 56, 38),
		gatorBelly = Color3.fromRGB(150, 140, 100),
		gatorEye = Color3.fromRGB(230, 200, 60),
		alum = Color3.fromRGB(150, 155, 160),
		navy = Color3.fromRGB(40, 55, 90),
		matWood = Color3.fromRGB(120, 92, 64),
		mud = Color3.fromRGB(84, 66, 44),
		canopy = Color3.fromRGB(40, 110, 190),
	}

	local rng
	local floating -- Site.Floating: lily pads, logs, the boat. Wildlife lifts them as the water rises.

	---------------------------------------------------------------- helpers

	local function part(parent, name, size, cf, color, material, shape)
		local p = Instance.new("Part")
		p.Name = name
		if shape then p.Shape = shape end
		p.Size, p.CFrame, p.Color = size, cf, color
		p.Material = material or Enum.Material.Plastic
		p.Anchored = true
		p.TopSurface, p.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
		p.Parent = parent
		return p
	end

	local function ghost(p)
		p.Transparency, p.CanCollide, p.CanQuery, p.CanTouch, p.CastShadow = 1, false, false, false, false
		return p
	end

	-- vertical cylinder standing on pos
	local function column(parent, name, height, diameter, pos, color, material)
		return part(parent, name, Vector3.new(height, diameter, diameter),
			CFrame.new(pos + Vector3.new(0, height / 2, 0)) * CFrame.Angles(0, 0, math.rad(90)),
			color, material, Enum.PartType.Cylinder)
	end

	-- block from a to b
	local function strut(parent, name, a, b, width, color)
		return part(parent, name, Vector3.new(width, width, (b - a).Magnitude), CFrame.lookAt((a + b) / 2, b), color)
	end

	local function model(parent, name)
		local m = Instance.new("Model")
		m.Name = name
		m.Parent = parent
		return m
	end

	local function ensure(parent, class, name)
		local x = parent:FindFirstChild(name)
		if not x then
			x = Instance.new(class)
			x.Name = name
			x.Parent = parent
		end
		return x
	end

	-- every sign in the site faces +Z, toward the spawn
	local function surface(p, ppu)
		local g = Instance.new("SurfaceGui")
		g.Face = Enum.NormalId.Back
		g.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud
		g.PixelsPerStud = ppu or 60
		g.LightInfluence = 0
		g.Parent = p
		return g
	end

	local function label(parent, name, text, size, pos, color, font, bg)
		local t = Instance.new("TextLabel")
		t.Name, t.Text, t.Size, t.Position = name, text, size, pos
		t.TextColor3, t.Font, t.TextScaled = color, font or Enum.Font.GothamBold, true
		t.BorderSizePixel = 0
		t.BackgroundTransparency = bg and 0 or 1
		if bg then t.BackgroundColor3 = bg end
		t.Parent = parent
		return t
	end

	---------------------------------------------------------------- pieces

	local function plumbing()
		local sim = ensure(ReplicatedStorage, "Folder", "SimEvents")
		for _, n in ipairs({ "Strike", "Weather", "Water", "PresenceChanged" }) do
			ensure(sim, "BindableEvent", n)
		end
		for _, n in ipairs({ "FlashEvent", "ScenarioControl", "ScenarioState", "StrikeHere", "StrikeRadar" }) do
			ensure(ReplicatedStorage, "RemoteEvent", n)
		end
		local thunder = ensure(ReplicatedStorage, "Sound", "Thunder")
		if thunder.SoundId == "" then
			-- "Thunder Sharp Booming Strikes Rumbling 1", ProSoundEffects, Roblox licensed library audio, 12.9 s.
			-- A deep boom with a long tail, which is what the mic listener's 120 Hz band pass hears best.
			thunder.SoundId = "rbxassetid://9120021540"
		end
	end

	local function terrain()
		local T = workspace.Terrain
		T:Clear()
		T:FillBlock(CFrame.new(0, -8, 0), Vector3.new(2048, 16, 2048), Enum.Material.Grass)
		T:FillBlock(CFrame.new(-620, -8, 0), Vector3.new(800, 16, 2048), Enum.Material.LeafyGrass) -- dry pine flatwoods west
		for _, s in ipairs(SWAMP) do
			local c, r = s[1], s[2]
			T:FillCylinder(CFrame.new(c.X, -8, c.Z), 16, r + 16, Enum.Material.Mud) -- muddy bank
			T:FillCylinder(CFrame.new(c.X, -3, c.Z), 6, r, Enum.Material.Air)
			T:FillCylinder(CFrame.new(c.X, -3.25, c.Z), 5.5, r, Enum.Material.Water)
		end
		T:FillBlock(CFrame.new(0, -8, 0), Vector3.new(112, 16, 112), Enum.Material.Ground) -- work pad, stays dry
		T:FillBlock(CFrame.new(0, -8, 520), Vector3.new(28, 16, 930), Enum.Material.Mud) -- access road
		pcall(function() T.Decoration = true end) -- swaying grass; not scriptable in every Studio, tick Terrain > Decoration by hand
		T.WaterColor = Color3.fromRGB(52, 66, 40)
		T.WaterTransparency, T.WaterReflectance = 0.7, 0.35
		T.WaterWaveSize, T.WaterWaveSpeed = 0.03, 3
		T:SetMaterialColor(Enum.Material.Grass, Color3.fromRGB(92, 120, 58))
		T:SetMaterialColor(Enum.Material.LeafyGrass, Color3.fromRGB(110, 118, 64))
		T:SetMaterialColor(Enum.Material.Ground, Color3.fromRGB(132, 116, 88))
		T:SetMaterialColor(Enum.Material.Mud, Color3.fromRGB(78, 64, 46))
	end

	local function beacon()
		local m = model(workspace, "Beacon")
		local base = part(m, "Base", Vector3.new(0.7, 10, 0.7), CFrame.new(0, 5, 0), C.steel, Enum.Material.Metal)
		m.PrimaryPart = base
		part(m, "Footing", Vector3.new(3, 0.6, 3), CFrame.new(0, 0.3, 0), C.concrete, Enum.Material.Concrete)
		part(m, "Head", Vector3.new(4.4, 3.6, 1.4), CFrame.new(0, 8.2, 0), C.safety)
		-- the real unit's silhouette: a tilted solar panel behind the head, the sensor pod on a short mast, a whip antenna
		part(m, "SolarBracket", Vector3.new(0.3, 2.2, 0.3), CFrame.new(0, 6.2, -1.1) * CFrame.Angles(math.rad(-20), 0, 0), C.steel, Enum.Material.Metal)
		part(m, "SolarPanel", Vector3.new(3.4, 0.15, 2.4), CFrame.new(0, 7.3, -2) * CFrame.Angles(math.rad(35), 0, 0), Color3.fromRGB(28, 40, 72), Enum.Material.Glass)
		part(m, "PodMast", Vector3.new(0.25, 2.4, 0.25), CFrame.new(1.9, 11.2, 0), C.steel, Enum.Material.Metal)
		part(m, "SensorPod", Vector3.new(1.1, 0.9, 0.9), CFrame.new(1.9, 12.85, 0), C.white)
		part(m, "PodLens", Vector3.new(0.5, 0.5, 0.1), CFrame.new(1.9, 12.85, 0.46), C.dark, Enum.Material.Glass)
		part(m, "Antenna", Vector3.new(0.08, 3, 0.08), CFrame.new(-1.9, 11.5, 0), C.dark)

		-- status light
		column(m, "LightBase", 0.5, 2, Vector3.new(0, 10, 0), C.dark)
		local light = part(m, "Light", Vector3.new(1.6, 1.6, 1.6), CFrame.new(0, 11.2, 0), C.green, Enum.Material.Neon, Enum.PartType.Ball)
		local glow = Instance.new("PointLight")
		glow.Name, glow.Range, glow.Brightness, glow.Color = "Glow", 20, 3, C.green
		glow.Parent = light
		-- level tag floating over the light, readable from the spawn
		local tag = Instance.new("BillboardGui")
		tag.Name, tag.Size, tag.StudsOffset = "LevelTag", UDim2.fromOffset(190, 46), Vector3.new(0, 2.4, 0)
		tag.MaxDistance, tag.LightInfluence = 140, 0
		tag.Parent = light
		label(tag, "Level", "ALL CLEAR", UDim2.fromScale(1, 0.62), UDim2.new(), C.green)
		label(tag, "Sub", "HAZARD INDEX 0", UDim2.fromScale(1, 0.38), UDim2.fromScale(0, 0.62), C.white, Enum.Font.GothamMedium)

		-- countdown
		local display = part(m, "Display", Vector3.new(3.6, 1.3, 0.2), CFrame.new(0, 9.15, 0.75), C.black)
		label(surface(display), "Countdown", "--:--", UDim2.fromScale(1, 1), UDim2.new(), C.red, Enum.Font.Code, C.black)

		-- hazard index gauge
		local gauge = part(m, "Gauge", Vector3.new(3.6, 1.4, 0.2), CFrame.new(0, 7.45, 0.75), C.black)
		local g = surface(gauge)
		local band = Instance.new("Frame")
		band.Size, band.Position, band.BorderSizePixel = UDim2.fromScale(0.9, 0.1), UDim2.fromScale(0.05, 0.08), 0
		band.BackgroundColor3 = Color3.new(1, 1, 1)
		band.Parent = g
		local grad = Instance.new("UIGradient")
		grad.Color = ColorSequence.new({
			ColorSequenceKeypoint.new(0, C.green), ColorSequenceKeypoint.new(0.5, C.yellow), ColorSequenceKeypoint.new(1, C.red),
		})
		grad.Parent = band
		label(g, "Lo", "0", UDim2.fromScale(0.1, 0.25), UDim2.fromScale(0.03, 0.7), C.dim)
		label(g, "Hi", "10", UDim2.fromScale(0.1, 0.25), UDim2.fromScale(0.87, 0.7), C.dim)
		local hubCf = CFrame.new(0, 6.95, 0.95)
		part(m, "NeedleHub", Vector3.new(0.3, 0.3, 0.3), hubCf, C.dark, Enum.Material.Metal, Enum.PartType.Ball)
		part(m, "Needle", Vector3.new(0.08, 1, 0.06), hubCf * CFrame.Angles(0, 0, math.rad(90)) * CFrame.new(0, 0.5, 0), C.white, Enum.Material.Neon)

		-- equipment lockout LCD
		local lcd = part(m, "Lcd", Vector3.new(3.4, 1.1, 0.3), CFrame.new(0, 4.6, 0.5), C.black)
		local lg = surface(lcd)
		label(lg, "Line1", "RIG 1  RUNNING", UDim2.fromScale(0.94, 0.42), UDim2.fromScale(0.03, 0.06), C.lcdText, Enum.Font.Code, C.lcd)
		label(lg, "Line2", "BEACON LINK OK", UDim2.fromScale(0.94, 0.42), UDim2.fromScale(0.03, 0.52), C.lcdText, Enum.Font.Code, C.lcd)

		for k, v in pairs({
			Led = "green", Countdown = 0, Index = 0, Interlock = "running", Presence = false,
			Online = false, Lcd1 = "RIG 1  RUNNING", Lcd2 = "BEACON LINK OK", Alerts = "[]",
		}) do
			m:SetAttribute(k, v)
		end
	end

	local function zone()
		local z = ghost(part(workspace, "ZonePart", Vector3.new(ZONE, 14, ZONE), CFrame.new(0, 7, 0), C.safety))
		-- kept for BeaconVisuals, which tints it; invisible so the zone reads as a real taped off area
		local floor = part(z, "ZoneFloor", Vector3.new(ZONE, 0.05, ZONE), CFrame.new(0, 0.05, 0), C.green)
		floor.Transparency, floor.CanCollide, floor.CanQuery, floor.CastShadow = 1, false, false, false
		local h = ZONE / 2
		local corners = { Vector3.new(-h, 0, -h), Vector3.new(h, 0, -h), Vector3.new(h, 0, h), Vector3.new(-h, 0, h) }
		local tape = Color3.fromRGB(240, 200, 30)
		for i = 1, 4 do
			local a, b = corners[i], corners[i % 4 + 1]
			local count = math.floor((b - a).Magnitude / 7.5)
			local prev
			for k = 0, count - 1 do
				local p = a:Lerp(b, k / count)
				-- stakes driven into the muck, leaning a little like real ones do
				local stake = part(z, "Stake", Vector3.new(0.3, 5, 0.3), CFrame.new(p + Vector3.new(0, 1.5, 0)) * CFrame.Angles(math.rad(rng:NextNumber(-4, 4)), 0, math.rad(rng:NextNumber(-4, 4))), C.wood, Enum.Material.Wood)
				stake.CanCollide = false
				local att = Instance.new("Attachment")
				att.Position = Vector3.new(0, 1.8, 0)
				att.Parent = stake
				if prev then
					local band = Instance.new("Beam")
					band.Attachment0, band.Attachment1 = prev, att
					band.Width0, band.Width1, band.Segments = 0.3, 0.3, 6
					band.CurveSize0, band.CurveSize1 = -0.4, 0.4 -- a little sag between stakes
					band.Color = ColorSequence.new(tape)
					band.FaceCamera, band.LightInfluence = true, 1
					band.Parent = stake
				end
				prev = att
			end
			prev = nil
		end
	end

	local function barrier(parent, cf)
		part(parent, "Barrier", Vector3.new(6, 2.4, 1.2), cf * CFrame.new(0, 1.2, 0), C.white, Enum.Material.Concrete)
		part(parent, "BarrierBand", Vector3.new(6.02, 0.5, 1.22), cf * CFrame.new(0, 1.9, 0), C.orange)
	end

	local function excavator(cf)
		local function P(x, y, z) return (cf * CFrame.new(x, y, z)).Position end
		local m = model(workspace, "Excavator")
		part(m, "TrackL", Vector3.new(1.8, 2, 10), cf * CFrame.new(-2.8, 1, 0), C.tire)
		part(m, "TrackR", Vector3.new(1.8, 2, 10), cf * CFrame.new(2.8, 1, 0), C.tire)
		m.PrimaryPart = part(m, "Undercarriage", Vector3.new(4, 1.2, 7), cf * CFrame.new(0, 1.6, 0), C.steel, Enum.Material.Metal)
		-- everything above the slewing ring swings as one model, BeaconVisuals freezes it on lockout
		local up = model(m, "Upper")
		up.PrimaryPart = ghost(part(up, "Hub", Vector3.new(1, 1, 1), cf * CFrame.new(0, 2.6, 0), C.steel))
		part(up, "Body", Vector3.new(6.5, 2.8, 7), cf * CFrame.new(0, 3.6, 0.8), C.safety)
		part(up, "Counterweight", Vector3.new(6.5, 2, 1.6), cf * CFrame.new(0, 3.8, 4.8), C.dark)
		local cab = part(up, "Cab", Vector3.new(2.8, 3, 3), cf * CFrame.new(-1.8, 6.5, -1.2), C.glass, Enum.Material.Glass)
		cab.Transparency = 0.35
		part(up, "CabRoof", Vector3.new(3, 0.3, 3.2), cf * CFrame.new(-1.8, 8.1, -1.2), C.safety)
		strut(up, "Boom", P(1.4, 4.8, -1.8), P(1.4, 9.6, -9.4), 1.2, C.safety)
		strut(up, "Stick", P(1.4, 9.6, -9.4), P(1.4, 3.4, -10.6), 0.9, C.safety)
		part(up, "Bucket", Vector3.new(2.4, 1.8, 1.8), cf * CFrame.new(1.4, 2.6, -10.8), C.dark, Enum.Material.Metal)
	end

